"""Türkçe — Kur'an (quran_001 … quran_080)."""

T = {
"quran_001": ("Kur'an'ın ilk suresinin adı nedir?", ["Fatiha", "Bakara", "İhlas", "Nas"], "Fatiha, «Açılış», Kur'an'ın ilk suresidir."),
"quran_002": ("Kur'an kaç sureden oluşur?", ["114", "99", "100", "120"], "Kur'an 114 sureden oluşur."),
"quran_003": ("Kur'an'ın en uzun suresi hangisidir?", ["Bakara", "Fatiha", "Kevser", "Asr"], "Bakara, 286 ayetle Kur'an'ın en uzun suresidir."),
"quran_004": ("Kur'an'ın en kısa suresi hangisidir?", ["Kevser", "İhlas", "Asr", "Nasr"], "Kevser, 3 ayetle Kur'an'ın en kısa suresidir."),
"quran_005": ("Kur'an hangi dilde indirildi?", ["Arapça", "Aramice", "İbranice", "Farsça"], "Kur'an, Arapça olarak indirildiğini açıkça belirtir."),
"quran_006": ("İsa'nın annesinin adını taşıyan 19. surenin adı nedir?", ["Meryem", "Yusuf", "Kehf", "Tâhâ"], "Kur'an'ın 19. suresi, İsa peygamberin annesinin adıyla Meryem'dir."),
"quran_007": ("Kur'an'ın bir bölümüne ne denir?", ["Sure", "Hadis", "Cüz", "Tefsir"], "Kur'an, sure denilen bölümlere ayrılır."),
"quran_008": ("Kur'an'ın bir cümlesine (ayetine) ne denir?", ["Ayet", "Sure", "Hadis", "Rükû"], "Kur'an'ın her cümlesine «işaret» anlamına gelen ayet denir."),
"quran_009": ("Namazın her rekâtında okunması zorunlu olan sure hangisidir?", ["Fatiha", "İhlas", "Kevser", "Fil"], "Sahih bir hadise göre Fatiha'yı okumak namazın rükünlerindendir."),
"quran_010": ("Kur'an kime indirildi?", ["Peygamber Muhammed ﷺ'e", "Musa peygambere", "İsa peygambere", "Davud peygambere"], "Kur'an, Cebrail aracılığıyla Peygamber Muhammed ﷺ'e indirildi."),
"quran_011": ("Bakara suresinin meşhur 255. ayetine ne denir?", ["Âyetü'l-Kürsî", "Nur ayeti", "Oruç ayeti", "Borç ayeti"], "2:255 ayeti, Âyetü'l-Kürsî, Allah'ın yüceliğini anlatır: «Allah, O'ndan başka ilah yoktur, Hayy'dır…»"),
"quran_012": ("Hangi sure «Bismillahirrahmanirrahim» ile başlamaz?", ["Tevbe", "Fatiha", "Yasin", "Kehf"], "Tevbe (9. sure), besmele ile başlamayan tek suredir."),
"quran_013": ("Kur'an'ın en uzun ayetinin (2:282) konusu nedir?", ["Borçların yazılması", "Hac", "Oruç", "Miras"], "Kur'an'ın en uzun ayeti borçları yazmayı ve şahit tutmayı öğretir: dürüstlük korunur."),
"quran_014": ("Kur'an'ın indirilen ilk ayetleri hangi kelimeyle başlar?", ["İkra (Oku!)", "Kul (De ki!)", "Sebbih (Tesbih et!)", "Kütibe (Yazıldı)"], "İndirilen ilk ayetler «İkra» ile başlar: «Yaratan Rabbinin adıyla oku.»"),
"quran_015": ("Kur'an'a göre Kadir Gecesi kaç aydan hayırlıdır?", ["Bin aydan", "Yüz aydan", "On iki aydan", "Kırk aydan"], "«Kadir Gecesi bin aydan hayırlıdır»: Ramazan'ın bir gecesi bir ömür ibadetten değerlidir."),
"quran_016": ("Korunmak için okunan son iki sure Felak ve Nas'a ne denir?", ["Muavvizeteyn (iki koruyucu)", "Zehraveyn", "Mufassal", "Seb'u't-Tıval"], "Felak ve Nas'a «muavvizeteyn» denir: Allah'a sığınmak için okunurlar."),
"quran_017": ("Kur'an geleneksel olarak kaç cüze ayrılır?", ["30", "10", "60", "114"], "Kur'an 30 cüze ayrılır; bu, örneğin Ramazan'da bir ayda hatmetmeye yardımcı olur."),
"quran_018": ("Fatiha suresi kaç ayettir?", ["7", "3", "10", "14"], "Fatiha, namazın her rekâtında okunan yedi ayettir."),
"quran_019": ("Hangi sure bir madenin adını taşır?", ["Hadid (Demir)", "Nur (Işık)", "Ra'd (Gök gürültüsü)", "Duhan (Duman)"], "57. sure Hadid'dir: «Demiri indirdik; onda büyük bir güç ve insanlar için faydalar vardır.»"),
"quran_020": ("Kur'an hangi kıssayı «kıssaların en güzeli» diye adlandırır?", ["Yusuf kıssasını", "Nuh kıssasını", "Ashab-ı Kehf kıssasını", "Fil kıssasını"], "«Sana kıssaların en güzelini anlatıyoruz»: Yusuf kıssası böyle başlar."),
"quran_021": ("En uzun sure olan Bakara kaç ayettir?", ["286", "114", "200", "365"], "Bakara 286 ayettir: Kur'an'ın en uzun suresi."),
"quran_022": ("Hangi kısa sure «De ki: O Allah birdir» der?", ["İhlas", "Felak", "Nas", "Kevser"], "İhlas, dört ayette Allah'ın mutlak birliğini ilan eder."),
"quran_023": ("Kur'an yaklaşık kaç yılda indirildi?", ["23 yıl", "1 yıl", "10 yıl", "40 yıl"], "Kur'an yaklaşık 23 yıl boyunca, önce Mekke'de sonra Medine'de peyderpey indirildi."),
"quran_024": ("Kur'an'a göre insanlar için Allah'a ibadet amacıyla kurulan ilk Ev hangisidir?", ["Bekke'deki (Mekke) Kâbe", "Kuba Mescidi", "Beytülmakdis", "Peygamber ﷺ'in mescidi"], "«İnsanlar için kurulan ilk ev Bekke'deki mübarek evdir…»: Mekke'deki Kâbe."),
"quran_025": ("Hangi sure filin adını taşır?", ["Fil", "Nahl", "Neml", "Bakara"], "105. sure Fil, Ebrehe'nin Mekke önünde durdurulan fil ordusunu hatırlatır."),
"quran_026": ("Nahl suresi hangi böceğin adını taşır?", ["Bal arısı", "Karınca", "Örümcek", "Sinek"], "Nahl «bal arısı» demektir; Allah orada arıya yuvalarını yapmasını vahyeder (16:68)."),
"quran_027": ("Hangi sure karıncanın adını taşır?", ["Neml", "Nahl", "Ankebut", "En'am"], "Neml («Karınca», 27. sure), Süleyman'ın ordusu yaklaşırken türdeşlerini uyaran karıncayı anlatır."),
"quran_028": ("Ankebut suresinde Kur'an, Allah'tan başka dost edinenleri neye benzetir?", ["Kendine çürük bir yuva yapan örümceğe", "Kovanını yapan arıya", "Yiyecek biriktiren karıncaya", "Soluyan köpeğe"], "«Evlerin en çürüğü örümcek evidir» (29:41); surenin adı buradan gelir."),
"quran_029": ("Bakara suresi hangi hayvanın adını taşır?", ["İnek", "Deve", "At", "Koyun"], "Bakara («İnek»), İsrailoğullarına kesmeleri emredilen ineği hatırlatır (2:67)."),
"quran_030": ("6. sure En'am'ın adı ne anlama gelir?", ["Davarlar", "Kuşlar", "Bahçeler", "Yıldızlar"], "En'am «davarlar» demektir; sure, müşriklerin hayvanlar hakkında uydurduğu kuralları reddeder."),
"quran_031": ("Rahman suresinde hangi ayet defalarca tekrarlanır?", ["«Rabbinizin nimetlerinden hangisini yalanlarsınız?»", "«Allah en büyüktür»", "«De ki: O Allah birdir»", "«Hamd Allah'adır»"], "Bu nakarat («Fe bi eyyi âlâi rabbikümâ tükezzibân») 55. surede 31 kez tekrarlanır."),
"quran_032": ("Kehf suresine göre Ashab-ı Kehf ne kadar uyudu?", ["Üç yüz yıl ve dokuz yıl daha", "Yüz yıl", "Kırk yıl", "Bin yıl"], "«Mağaralarında üç yüz yıl kaldılar ve dokuz yıl daha eklediler» (18:25)."),
"quran_033": ("Ashab-ı Kehf'in yanında hangi hayvan vardı?", ["Bir köpek", "Bir kedi", "Bir eşek", "Bir keçi"], "«Köpekleri de girişte ön ayaklarını uzatmış yatıyordu» (18:18)."),
"quran_034": ("Kehf suresine göre Zülkarneyn hangi kavimlere karşı bir set yaptı?", ["Ye'cüc ve Me'cüc", "Âd ve Semud", "Romalılar", "Persler"], "Bir kavim ondan Ye'cüc ve Me'cüc'e karşı koruma istedi; demir ve bakırdan bir set yaptı (18:94-96)."),
"quran_035": ("Hangi ayet «Allah göklerin ve yerin nurudur» diye başlar?", ["Nur ayeti (Nur 24:35)", "Âyetü'l-Kürsî", "Borç ayeti", "Kehf ayeti"], "«Nur ayeti», O'nun nurunu içinde kandil bulunan bir kandilliğe benzetir (24:35)."),
"quran_036": ("Buhârî'deki bir hadise göre hangi sure Kur'an'ın üçte birine denktir?", ["İhlas", "Fatiha", "Yasin", "Kehf"], "Peygamber ﷺ «Kul hüvallahü ehad» hakkında «Kur'an'ın üçte birine denktir» dedi."),
"quran_037": ("Sahih-i Müslim'e göre Peygamber ﷺ Kur'an'ın en büyük ayeti olarak hangisini gösterdi?", ["Âyetü'l-Kürsî", "Fatiha'nın ilk ayeti", "Bakara'nın son ayeti", "Nur ayeti"], "Übey bin Ka'b'a en büyük ayetin hangisi olduğunu sordu; Übey Âyetü'l-Kürsî dedi ve Peygamber ﷺ onu tebrik etti."),
"quran_038": ("Mesed suresinde Peygamber ﷺ'in hangi düşmanının adı geçer?", ["Ebu Leheb", "Ebu Cehil", "Ebu Süfyan", "Velid"], "«Ebu Leheb'in elleri kurusun» (111:1): Peygamber ﷺ'in bu amcası ona açıkça düşmanlık etti."),
"quran_039": ("Kâfirun suresi nasıl biter?", ["«Sizin dininiz size, benim dinim bana»", "«Allah en büyüktür»", "«O'na denk hiçbir şey yoktur»", "«Hasetçinin şerrinden»"], "«Leküm dînüküm ve liye dîn» (109:6), İslam ile şirk arasındaki kesin ayrımı bildirir."),
"quran_040": ("Nasr suresi neyi anlatır?", ["Allah'ın yardımını ve insanların bölük bölük dine girişini", "Göğün yaratılışını", "Ramazan orucunu", "Yusuf kıssasını"], "«Allah'ın yardımı ve fetih geldiğinde ve insanların bölük bölük Allah'ın dinine girdiğini gördüğünde» (110:1-2)."),
"quran_041": ("Asr suresine göre kimler hüsrandan kurtulur?", ["İman edip salih amel işleyenler, birbirlerine hakkı ve sabrı tavsiye edenler", "Zenginler", "Güçlüler", "Yolcular"], "«İnsan hüsrandadır; ancak iman edip salih amel işleyenler, birbirlerine hakkı ve sabrı tavsiye edenler müstesna» (103:2-3)."),
"quran_042": ("Maun suresinde «hesabı yalanlayan» ne yapar?", ["Yetimi itip kakar ve yoksulu doyurmaya teşvik etmez", "Mescitleri yıkar", "Yolculuğu reddeder", "Malı hakkında yalan söyler"], "«İşte o, yetimi itip kakan ve yoksulu doyurmaya teşvik etmeyendir» (107:2-3)."),
"quran_043": ("İndirilen ilk ayetlere (Alak) göre Allah insanı neyden yarattı?", ["Bir alaktan (asılıp tutunan şey)", "Nurdan", "Ateşten", "Rüzgârdan"], "«Yaratan Rabbinin adıyla oku; O, insanı alaktan yarattı» (96:1-2)."),
"quran_044": ("Kur'an'daki «tekrarlanan yedi» (seb'u'l-mesânî) ifadesi neyi kasteder?", ["Fatiha'yı", "En uzun yedi sureyi", "Âyetü'l-Kürsî'yi", "Kur'an'ın son yedi ayetini"], "«Sana tekrarlanan yediyi ve yüce Kur'an'ı verdik» (15:87): her rekâtta okunan Fatiha."),
"quran_045": ("Kur'an'ın isimlerinden «Furkan» ne anlama gelir?", ["Hakkı batıldan ayıran", "Nur", "Zikir", "Şifa"], "«Furkan'ı kuluna indiren ne yücedir» (25:1): hakkı batıldan ayıran Kitap."),
"quran_046": ("Allah Tur suresinin başında neye yemin eder?", ["Tur dağına", "Güneşe", "İncire", "Geceye"], "«Tur'a andolsun! Yazılmış bir kitaba…» (52:1-2): Tur, Musa'nın vahiy aldığı dağdır."),
"quran_047": ("53. surenin adı «Necm» ne anlama gelir?", ["Yıldız", "Ay", "Güneş", "Şafak"], "«Battığı zaman yıldıza andolsun!» (53:1)."),
"quran_048": ("Kadir suresine göre Kadir Gecesi'nde kim iner?", ["Melekler ve Ruh (Cebrail)", "Peygamberler", "Cinler", "Rüzgârlar"], "«O gecede melekler ve Ruh, Rablerinin izniyle iner» (97:4)."),
"quran_049": ("Kur'an'a göre Kur'an müminler için nedir?", ["Şifa ve rahmet", "Sadece bir şiir", "Bir tarih kitabı", "Bir takvim"], "«Kur'an'dan müminler için şifa ve rahmet olan şeyler indiriyoruz» (17:82)."),
"quran_050": ("Kur'an, ilahi kaynağından şüphe edenlere hangi meydan okumayı yapar?", ["Benzeri tek bir sure getirmelerini", "Kur'an'ın tamamını ezbere okumalarını", "Kur'an'ı çevirmelerini", "Bir mescit yapmalarını"], "«İndirdiğimizden şüphe ediyorsanız, onun benzeri bir sure getirin» (2:23)."),
"quran_051": ("Hangi sureye «Ümmü'l-Kur'an» (Kur'an'ın anası) denir?", ["Fatiha", "Bakara", "Yasin", "İhlas"], "Peygamber ﷺ dedi ki: «Ümmü'l-Kur'an, tekrarlanan yedi ve yüce Kur'an'dır.»"),
"quran_052": ("«Mekkî» sure ne demektir?", ["Hicretten önce inen sure", "Medine'de inen sure", "Kâbe hakkındaki sure", "Çok kısa sure"], "Âlimler sureleri döneme göre sınıflar: Medine'ye hicretten önce (Mekkî) veya sonra (Medenî)."),
"quran_053": ("Kaç sure «Elif, Lâm, Mîm» harfleriyle başlar?", ["Altı", "İki", "On", "Bir"], "Bakara, Âl-i İmran, Ankebut, Rum, Lokman ve Secde «Elif, Lâm, Mîm» ile başlar."),
"quran_054": ("Bazı surelerin başındaki tek tek harflere (Elif Lâm Mîm, Yâ Sîn, Kâf…) ne denir?", ["Hurûf-ı mukattaa (kesik harfler)", "Mensuh ayetler", "Şemsî harfler", "Tecvid harfleri"], "Yirmi dokuz sure bu harflerle başlar; tam anlamını yalnızca Allah bilir."),
"quran_055": ("Hangi sure Peygamber Muhammed ﷺ'in adını taşır?", ["47. sure, Muhammed", "1. sure, Fatiha", "36. sure, Yasin", "112. sure, İhlas"], "47. surenin adı «Muhammed»dir; 2. ayetinde adı geçer."),
"quran_056": ("Kur'an'da geçen Lokman'ın oğluna ilk öğüdü nedir?", ["Allah'a hiçbir şeyi ortak koşmamak", "Yıldızları incelemek", "Tüccar olmak", "Uzaklara gitmek"], "«Yavrum, Allah'a ortak koşma; şüphesiz şirk büyük bir zulümdür» (31:13)."),
"quran_057": ("Tevbe suresi başka hangi adla bilinir?", ["Berâe (ilişik kesme)", "Nur", "Enfal", "Fetih"], "İlk kelimesi «Berâe»dir: Allah ve Resulünden müşriklere bir ültimatom (9:1)."),
"quran_058": ("Hangi sure «Yâ, Sîn» harfleriyle başlar?", ["Yasin (36. sure)", "Tâhâ", "Kâf", "Sâd"], "36. sure «Yâsîn. Hikmetli Kur'an'a andolsun!» diye başlar."),
"quran_059": ("67. surenin adı «Mülk» ne anlama gelir?", ["Hükümranlık / egemenlik", "Nur", "Yolculuk", "Zafer"], "«Mülk elinde olan ne yücedir» (67:1)."),
"quran_060": ("Kur'an'ın son suresi hangisidir?", ["Nas", "Felak", "İhlas", "Fatiha"], "Nas («İnsanlar»), 114. sure, Kur'an'ı bitirir: «De ki: insanların Rabbine sığınırım.»"),
"quran_061": ("Felak suresi nasıl başlar?", ["«De ki: sabahın Rabbine sığınırım»", "«De ki: O Allah birdir»", "«Asra andolsun!»", "«Hamd Allah'adır»"], "«Kul eûzü bi rabbi'l-felak» (113:1): Felak, tan yeri demektir."),
"quran_062": ("Kur'an hangi iki tepeyi «Allah'ın şiarlarından» sayar?", ["Safa ve Merve", "Uhud ve Sevr", "Arafat ve Mina", "Hira ve Ebu Kubeys"], "«Safa ve Merve Allah'ın şiarlarındandır» (2:158): haccın sa'yi bunların arasında yapılır."),
"quran_063": ("Kur'an'da adı geçen tek kadın kimdir?", ["Meryem", "Hatice", "Asiye", "Hacer"], "İsa'nın annesi Meryem'in adı birçok surede geçer ve bütün bir sure onun adını taşır."),
"quran_064": ("Kur'an'da adı geçen tek sahabi kimdir?", ["Zeyd bin Harise", "Ebu Bekir", "Ömer", "Ali"], "«Zeyd ondan ilişiğini kesince…» (33:37): Peygamber ﷺ'in azatlısı Zeyd, adı geçen tek sahabidir."),
"quran_065": ("Bakara suresinde anılan Harut ve Marut kimdi?", ["Babil'e gönderilen iki melek", "İki peygamber", "Mısır'ın iki kralı", "İki sahabi"], "«…Babil'deki iki melek Harut ve Marut'a indirileni» (2:102): büyünün bir imtihan olduğunu söylüyorlardı."),
"quran_066": ("Kur'an'a göre Allah katında en değerli kimdir?", ["En takvalı olan", "En zengin", "En güçlü", "En ünlü"], "«Allah katında en değerliniz en takvalı olanınızdır» (49:13)."),
"quran_067": ("56. surenin adı «Vâkıa» neyi ifade eder?", ["Kaçınılmaz olayı (Kıyamet gününü)", "Kervanı", "Karıncayı", "Gece yolculuğunu"], "«Vâkıa vuku bulduğunda…» (56:1): sure, kıyamet gününün üç grubunu anlatır."),
"quran_068": ("Allah Kalem suresinin başında hangi nesneye yemin eder?", ["Kaleme", "Kılıca", "Teraziye", "Kandile"], "«Nûn. Kaleme ve yazdıklarına andolsun!» (68:1)."),
"quran_069": ("Fecr suresi nasıl başlar?", ["Fecre ve on geceye yeminle", "İncire yeminle", "Yusuf kıssasıyla", "Yalnızca besmeleyle"], "«Fecre andolsun! On geceye andolsun!» (89:1-2)."),
"quran_070": ("Allah Şems suresinin başında hangi gök cismine yemin eder?", ["Güneşe", "Yalnızca aya", "Yıldızlara", "Gezegenlere"], "«Güneşe ve aydınlığına andolsun!» (91:1); Şems «güneş» demektir."),
"quran_071": ("Hangi sure «İnsanın üzerinden, henüz anılmaya değer bir şey olmadığı uzun bir süre geçmedi mi?» diye başlar?", ["İnsan (76. sure)", "Kehf", "Hac", "Fatiha"], "Dehr de denilen İnsan suresi, insanın yaratılmadan önce hiçbir şey olmadığını hatırlatır (76:1)."),
"quran_072": ("Kur'an'a göre Allah Kur'an'ı ne için kolaylaştırdı?", ["Anmak ve ezberlemek için", "Ticaret için", "Çeviri için", "Unutmak için"], "«Andolsun Kur'an'ı öğüt almak için kolaylaştırdık; öğüt alan var mı?» (54:17), surede dört kez tekrarlanır."),
"quran_073": ("Kamer suresi ilk ayetinde hangi mucizeyi anar?", ["Ayın yarılmasını", "Güneşin sönmesini", "Denizin açılmasını", "Dağın konuşmasını"], "«Kıyamet yaklaştı ve ay yarıldı» (54:1): Mekkelilere gösterilen bir mucize."),
"quran_074": ("Kur'an'ın kendisine göre, Kur'an neden bir defada değil peyderpey indirildi?", ["Peygamber ﷺ'in kalbini sağlamlaştırmak için", "Çok uzun olduğu için", "Düşmanlardan gizlemek için", "Yolculuklar yüzünden"], "«Böyle yaptık ki onunla kalbini sağlamlaştıralım; onu tane tane okuduk» (25:32)."),
"quran_075": ("Aişe'ye göre Peygamber ﷺ her gece uyumadan önce hangi sureleri ellerine okurdu?", ["İhlas, Felak ve Nas", "Fatiha ve Bakara", "Yasin ve Mülk", "Kehf ve Meryem"], "Üç «Kul» suresini okuyup ellerine üfler, sonra ellerini bedenine üç kez sürerdi."),
"quran_076": ("Kur'an'ın bazı ayetleri okunurken yapılan secdeye ne denir?", ["Tilavet secdesi", "Sehiv secdesi", "Şükür secdesi", "Rükû"], "Kur'an'da secde ayetleri vardır; Alak suresinin son ayeti gibi: «secde et ve yaklaş» (96:19)."),
"quran_077": ("Kur'an'ın doğru okunuş kurallarının ilmine ne denir?", ["Tecvid", "Tefsir", "Fıkıh", "Siyer"], "Tecvid, her harfi mahrecinden ve sıfatlarıyla telaffuz etmeyi öğretir."),
"quran_078": ("Kur'an'ın tamamını ezberleyen kişiye ne denir?", ["Hafız", "İmam", "Müezzin", "Müftü"], "Hafız «koruyan» demektir: Kur'an'ın tamamını hafızasında taşır."),
"quran_079": ("Kur'an'ın yazılı nüshasına ne denir?", ["Mushaf", "Hadis", "Cüz", "Minber"], "Mushaf, iki kapak arasında toplanmış Kur'an'dır; cüz ise otuz parçasından biridir."),
"quran_080": ("Hangi surede besmele iki kez geçer?", ["Neml", "Fatiha", "Tevbe", "Bakara"], "Neml suresi, başındaki besmeleye ek olarak Süleyman'ın Sebe melikesine mektubunun başında besmeleyi anar (27:30)."),
}
